'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['applyLedgerCredit']);
const { applyLedgerCredit } = api;

const original = [
  { key: 'a', reserve: 2, bonus: 3, tokens: 4 },
  { key: 'b', reserve: 5, bonus: 6, tokens: 7 }
];
const snapshot = structuredClone(original);
const result = applyLedgerCredit('credit:bonus', 'b', 2, original);
assert.deepStrictEqual(result, {
  ok: true,
  accounts: [
    { key: 'a', reserve: 2, bonus: 3, tokens: 4 },
    { key: 'b', reserve: 5, bonus: 8, tokens: 7 }
  ],
  message: 'bonus credited by 2; new balance: 8.'
});
assert.deepStrictEqual(original, snapshot);
assert.notStrictEqual(result.accounts, original);
for (let i = 0; i < original.length; i++) {
  assert.notStrictEqual(result.accounts[i], original[i]);
}
result.accounts[0].reserve = 99;
assert.deepStrictEqual(original, snapshot);

assert.deepStrictEqual(
  applyLedgerCredit('credit:tokens', 'a', 3, original),
  {
    ok: true,
    accounts: [
      { key: 'a', reserve: 2, bonus: 3, tokens: 7 },
      { key: 'b', reserve: 5, bonus: 6, tokens: 7 }
    ],
    message: 'tokens credited by 3; new balance: 7.'
  }
);
assert.deepStrictEqual(original, snapshot);

const absentInput = [{ key: 'a', reserve: 1, bonus: 2, tokens: 3 }];
const absent = applyLedgerCredit('credit:tokens', 'missing', 1, absentInput);
assert.deepStrictEqual(absent, {
  ok: false,
  accounts: [{ key: 'a', reserve: 1, bonus: 2, tokens: 3 }],
  message: 'Account missing was not found.'
});
assert.notStrictEqual(absent.accounts, absentInput);
assert.notStrictEqual(absent.accounts[0], absentInput[0]);
assert.deepStrictEqual(applyLedgerCredit('credit:reserve', 'x', 1, []), {
  ok: false,
  accounts: [],
  message: 'Account x was not found.'
});

const max = Number.MAX_SAFE_INTEGER;
assert.deepStrictEqual(
  applyLedgerCredit('credit:reserve', 'max', max, [
    { key: 'max', reserve: 0, bonus: 0, tokens: 0 }
  ]).accounts[0],
  { key: 'max', reserve: max, bonus: 0, tokens: 0 }
);
assert.throws(() => applyLedgerCredit('credit:reserve', 'x', 1, [
  { key: 'x', reserve: max, bonus: 0, tokens: 0 }
]), RangeError);

for (const args of [
  ['credit:other', 'x', 1, []],
  [null, 'x', 1, []],
  ['credit:reserve', '', 1, []],
  ['credit:reserve', 1, 1, []],
  ['credit:reserve', 'x', '1', []],
  ['credit:reserve', 'x', 1, null],
  ['credit:reserve', 'x', 1, [{ key: '', reserve: 0, bonus: 0, tokens: 0 }]],
  ['credit:reserve', 'x', 1, [{ key: 'x', reserve: '0', bonus: 0, tokens: 0 }]]
]) {
  assert.throws(() => applyLedgerCredit(...args), TypeError);
}

for (const amount of [0, -1, 1.5, max + 1]) {
  assert.throws(() => applyLedgerCredit('credit:reserve', 'x', amount, []), RangeError);
}
for (const record of [
  { key: 'x', reserve: -1, bonus: 0, tokens: 0 },
  { key: 'x', reserve: 0.5, bonus: 0, tokens: 0 },
  { key: 'x', reserve: max + 1, bonus: 0, tokens: 0 }
]) {
  assert.throws(() => applyLedgerCredit('credit:reserve', 'absent', 1, [record]), RangeError);
}
assert.throws(() => applyLedgerCredit('credit:reserve', 'absent', 1, [
  { key: 'x', reserve: 0, bonus: 0, tokens: 0 },
  { key: 'x', reserve: 1, bonus: 1, tokens: 1 }
]), RangeError);

const sparseFirst = { key: 'hit', reserve: 4, bonus: 5, tokens: 6 };
const sparseAccounts = [sparseFirst];
sparseAccounts.length = 2;
assert.strictEqual(Object.hasOwn(sparseAccounts, 1), false);
const sparseSnapshot = { ...sparseFirst };
assert.throws(
  () => applyLedgerCredit('credit:reserve', 'hit', 1, sparseAccounts),
  TypeError
);
assert.deepStrictEqual(sparseFirst, sparseSnapshot);
assert.strictEqual(Object.hasOwn(sparseAccounts, 1), false);

const denseFirst = { key: 'hit', reserve: 4, bonus: 5, tokens: 6 };
const denseMalformed = [
  denseFirst,
  { key: 'other', reserve: 0, bonus: null, tokens: 0 }
];
const denseFirstSnapshot = { ...denseFirst };
assert.throws(
  () => applyLedgerCredit('credit:reserve', 'hit', 1, denseMalformed),
  TypeError
);
assert.deepStrictEqual(denseFirst, denseFirstSnapshot);

