function createRunSheet(initialEntries = []) {
  function copyAndValidate(source) {
    if (!Array.isArray(source)) throw new TypeError('Entries must be an array');

    const seen = new Set();
    const copies = [];
    for (let index = 0; index < source.length; index += 1) {
      const entry = source[index];
      if (!entry || typeof entry !== 'object' || Array.isArray(entry) ||
          typeof entry.id !== 'string' || entry.id.length === 0) {
        throw new TypeError('Invalid entry');
      }

      for (const field of ['minutes', 'repeats']) {
        if (typeof entry[field] !== 'number') {
          throw new TypeError('Numeric fields must be numbers');
        }
        if (!Number.isSafeInteger(entry[field]) || entry[field] <= 0) {
          throw new RangeError('Numeric fields must be positive safe integers');
        }
      }

      if (seen.has(entry.id)) throw new RangeError('Duplicate id');
      seen.add(entry.id);
      copies.push({
        id: entry.id,
        minutes: entry.minutes,
        repeats: entry.repeats
      });
    }
    return copies;
  }

  let entries = copyAndValidate(initialEntries);

  return {
    list() {
      return entries.map((entry) => ({
        id: entry.id,
        minutes: entry.minutes,
        repeats: entry.repeats
      }));
    },

    totalMinutes() {
      return entries.reduce((total, entry) => {
        const value = entry.minutes * entry.repeats;
        if (!Number.isSafeInteger(value) || !Number.isSafeInteger(total + value)) {
          throw new RangeError('Total overflow');
        }
        return total + value;
      }, 0);
    },

    upsert(entry) {
      const copy = copyAndValidate([entry])[0];
      const index = entries.findIndex((item) => item.id === copy.id);
      if (index === -1) entries.push(copy);
      else entries[index] = copy;
    },

    replace(next) {
      const copies = copyAndValidate(next);
      entries = copies;
    },

    remove(id) {
      if (typeof id !== 'string') throw new TypeError('Id must be a string');
      const index = entries.findIndex((entry) => entry.id === id);
      if (index === -1) return false;
      entries.splice(index, 1);
      return true;
    },

    clear() {
      entries = [];
    }
  };
}

module.exports = { createRunSheet };

