'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createRunSheet']);
const { createRunSheet } = api;

const empty = createRunSheet();
assert.deepStrictEqual(empty.list(), []);
assert.strictEqual(empty.totalMinutes(), 0);
assert.strictEqual(empty.remove(''), false);
empty.clear();
assert.deepStrictEqual(empty.list(), []);

const initial = [
  { id: 'a', minutes: 2, repeats: 3 },
  { id: 'b', minutes: 5, repeats: 1 }
];
const initialSnapshot = structuredClone(initial);
const sheet = createRunSheet(initial);
assert.deepStrictEqual(initial, initialSnapshot);
initial[0].minutes = 99;
initial.push({ id: 'c', minutes: 1, repeats: 1 });
assert.deepStrictEqual(sheet.list(), initialSnapshot);
assert.strictEqual(sheet.totalMinutes(), 11);
const firstList = sheet.list();
const secondList = sheet.list();
assert.notStrictEqual(firstList, secondList);
assert.notStrictEqual(firstList[0], secondList[0]);
firstList[0].minutes = 500;
assert.deepStrictEqual(sheet.list(), initialSnapshot);

const replacement = { id: 'a', minutes: 4, repeats: 2 };
sheet.upsert(replacement);
replacement.minutes = 100;
assert.deepStrictEqual(sheet.list(), [
  { id: 'a', minutes: 4, repeats: 2 },
  { id: 'b', minutes: 5, repeats: 1 }
]);
const appended = { id: 'c', minutes: 1, repeats: 7 };
sheet.upsert(appended);
appended.repeats = 100;
assert.deepStrictEqual(sheet.list(), [
  { id: 'a', minutes: 4, repeats: 2 },
  { id: 'b', minutes: 5, repeats: 1 },
  { id: 'c', minutes: 1, repeats: 7 }
]);
assert.strictEqual(sheet.remove('b'), true);
assert.strictEqual(sheet.remove('b'), false);
assert.deepStrictEqual(sheet.list().map(entry => entry.id), ['a', 'c']);

const next = [{ id: 'z', minutes: 3, repeats: 3 }];
sheet.replace(next);
next[0].minutes = 30;
next.push({ id: 'q', minutes: 1, repeats: 1 });
assert.deepStrictEqual(sheet.list(), [{ id: 'z', minutes: 3, repeats: 3 }]);
assert.strictEqual(sheet.totalMinutes(), 9);

const beforeInvalidReplace = sheet.list();
assert.throws(() => sheet.replace([
  { id: 'valid', minutes: 1, repeats: 1 },
  { id: 'valid', minutes: 2, repeats: 2 }
]), RangeError);
assert.deepStrictEqual(sheet.list(), beforeInvalidReplace);
assert.strictEqual(sheet.totalMinutes(), 9);
assert.throws(() => sheet.replace([
  { id: 'valid', minutes: 1, repeats: 1 },
  { id: 'bad', minutes: 0, repeats: 1 }
]), RangeError);
assert.deepStrictEqual(sheet.list(), beforeInvalidReplace);
assert.throws(() => sheet.upsert({ id: 'bad', minutes: '1', repeats: 1 }), TypeError);
assert.deepStrictEqual(sheet.list(), beforeInvalidReplace);
assert.throws(() => sheet.remove(3), TypeError);
assert.deepStrictEqual(sheet.list(), beforeInvalidReplace);

const oneHole = new Array(1);
assert.strictEqual(Object.hasOwn(oneHole, 0), false);
assert.throws(() => sheet.replace(oneHole), TypeError);
assert.deepStrictEqual(sheet.list(), beforeInvalidReplace);
assert.strictEqual(sheet.totalMinutes(), 9);

const validPrefixThenHole = [{ id: 'prefix', minutes: 2, repeats: 2 }];
validPrefixThenHole.length = 2;
assert.strictEqual(Object.hasOwn(validPrefixThenHole, 1), false);
assert.throws(() => sheet.replace(validPrefixThenHole), TypeError);
assert.deepStrictEqual(sheet.list(), beforeInvalidReplace);
assert.strictEqual(sheet.totalMinutes(), 9);

sheet.clear();
assert.deepStrictEqual(sheet.list(), []);
assert.strictEqual(sheet.totalMinutes(), 0);

for (const entries of [null, {}, 'x']) {
  assert.throws(() => createRunSheet(entries), TypeError);
}
for (const entry of [
  null,
  {},
  { id: '', minutes: 1, repeats: 1 },
  { id: 2, minutes: 1, repeats: 1 },
  { id: 'x', minutes: '1', repeats: 1 },
  { id: 'x', minutes: 1, repeats: '1' }
]) {
  assert.throws(() => createRunSheet([entry]), TypeError);
}
for (const entry of [
  { id: 'x', minutes: 0, repeats: 1 },
  { id: 'x', minutes: -1, repeats: 1 },
  { id: 'x', minutes: 1.5, repeats: 1 },
  { id: 'x', minutes: Number.MAX_SAFE_INTEGER + 1, repeats: 1 },
  { id: 'x', minutes: 1, repeats: 0 }
]) {
  assert.throws(() => createRunSheet([entry]), RangeError);
}
assert.throws(() => createRunSheet([
  { id: 'x', minutes: 1, repeats: 1 },
  { id: 'x', minutes: 2, repeats: 2 }
]), RangeError);

const constructorHole = new Array(1);
assert.strictEqual(Object.hasOwn(constructorHole, 0), false);
assert.throws(() => createRunSheet(constructorHole), TypeError);
const constructorPrefixHole = [{ id: 'x', minutes: 1, repeats: 1 }];
constructorPrefixHole.length = 2;
assert.throws(() => createRunSheet(constructorPrefixHole), TypeError);

const productOverflow = createRunSheet([
  { id: 'x', minutes: Number.MAX_SAFE_INTEGER, repeats: 2 }
]);
assert.throws(() => productOverflow.totalMinutes(), RangeError);
const sumOverflow = createRunSheet([
  { id: 'x', minutes: Number.MAX_SAFE_INTEGER, repeats: 1 },
  { id: 'y', minutes: 1, repeats: 1 }
]);
assert.throws(() => sumOverflow.totalMinutes(), RangeError);

