function valid(item) {
  return item && Number.isInteger(item.id) && item.id > 0 &&
    typeof item.name === 'string' && item.name.length > 0 &&
    typeof item.maker === 'string' && item.maker.length > 0 &&
    Number.isInteger(item.released) && item.released >= 0 && item.released <= 9999;
}

function validId(id) {
  return Number.isInteger(id) && id > 0;
}

function copy(item) {
  return { id: item.id, name: item.name, maker: item.maker, released: item.released };
}

function copies(catalog) {
  const result = [];
  for (let index = 0; index < catalog.length; index += 1) {
    result.push(copy(catalog[index]));
  }
  return result;
}

function applyCatalogCommand(catalog, command) {
  if (!Array.isArray(catalog)) {
    return { status: 400, data: { error: 'Invalid input' }, catalog: [] };
  }
  for (let index = 0; index < catalog.length; index += 1) {
    if (!valid(catalog[index])) {
      return { status: 400, data: { error: 'Invalid input' }, catalog: [] };
    }
  }

  const current = copies(catalog);
  const invalid = () => ({ status: 400, data: { error: 'Invalid input' }, catalog: copies(current) });
  const missing = () => ({ status: 404, data: { error: 'Item not found' }, catalog: copies(current) });
  if (!command || typeof command !== 'object' || Array.isArray(command)) return invalid();

  if (command.type === 'readAll') {
    return { status: 200, data: copies(current), catalog: copies(current) };
  }
  if (command.type === 'read' && validId(command.id)) {
    const item = current.find((entry) => entry.id === command.id);
    return item ? { status: 200, data: copy(item), catalog: copies(current) } : missing();
