  if (command.type === 'create' && valid(command.item)) {
    if (current.some((entry) => entry.id === command.item.id)) {
      return { status: 409, data: { error: 'Duplicate id' }, catalog: copies(current) };
    }
    const item = copy(command.item);
    current.push(item);
    return { status: 201, data: copy(item), catalog: copies(current) };
  }
  if (command.type === 'replace' && validId(command.id) && valid(command.item) && command.item.id === command.id) {
    const index = current.findIndex((entry) => entry.id === command.id);
    if (index < 0) return missing();
    current[index] = copy(command.item);
    return { status: 200, data: copy(current[index]), catalog: copies(current) };
