assert.deepStrictEqual(sharedWithSparseMedia.author, outerSnapshot.author);
assert.deepStrictEqual(sharedWithSparseMedia.counts, outerSnapshot.counts);
assert.deepStrictEqual(sharedActivity.media[0], { type: 'image', source: 'first.png' });
assert.strictEqual(Object.hasOwn(sharedActivity.media, 1), false);

const selfCycle = valid();
