'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createRecipeBook']);
const { createRecipeBook } = api;
assert.throws(() => createRecipeBook(), TypeError);
assert.throws(() => createRecipeBook({}), TypeError);

(async () => {
  const events = [];
  const book = createRecipeBook(event => {
    events.push(event);
    return 'ignored';
  });
  assert.deepStrictEqual(Object.keys(book).sort(), ['add', 'get', 'remove', 'update']);
  for (const name of ['add', 'get', 'update', 'remove']) {
    assert.strictEqual(typeof book[name], 'function');
  }

  const input = { key: 'k1', title: '  Soup  ', ingredients: ['water', ' '] };
  const added = await book.add(input);
  assert.deepStrictEqual(added, input);
  assert.notStrictEqual(added, input);
  assert.notStrictEqual(added.ingredients, input.ingredients);
  input.title = 'changed';
  input.ingredients[0] = 'changed';
  added.ingredients[1] = 'returned change';
  assert.deepStrictEqual(await book.get('k1'), {
    key: 'k1',
    title: '  Soup  ',
    ingredients: ['water', ' ']
  });

  const get1 = await book.get('k1');
  const get2 = await book.get('k1');
  assert.notStrictEqual(get1, get2);
  assert.notStrictEqual(get1.ingredients, get2.ingredients);
  get1.ingredients.push('pepper');
  assert.deepStrictEqual(get2.ingredients, ['water', ' ']);
  assert.strictEqual(await book.get('absent'), null);

  const changes = { title: ' Stew ', ingredients: ['beans'] };
  const updated = await book.update('k1', changes);
  assert.deepStrictEqual(updated, {
    key: 'k1',
    title: ' Stew ',
    ingredients: ['beans']
  });
  changes.title = 'mutated';
  changes.ingredients[0] = 'mutated';
  updated.ingredients[0] = 'returned mutation';
  assert.deepStrictEqual(await book.get('k1'), {
    key: 'k1',
    title: ' Stew ',
    ingredients: ['beans']
  });

  const beforeInvalid = await book.get('k1');
  const invalidUpdateEventStart = events.length;
  let invalidUpdateError;
  try {
    await book.update('k1', { title: '   ' });
  } catch (error) {
    invalidUpdateError = error;
  }
  assert.ok(invalidUpdateError instanceof TypeError);
  assert.deepStrictEqual(await book.get('k1'), beforeInvalid);
  assert.deepStrictEqual(events[invalidUpdateEventStart], {
    operation: 'update',
    phase: 'start'
  });
  assert.strictEqual(events[invalidUpdateEventStart + 1].operation, 'update');
  assert.strictEqual(events[invalidUpdateEventStart + 1].phase, 'failure');
  assert.strictEqual(events[invalidUpdateEventStart + 1].error, invalidUpdateError);

  let duplicateError;
  try {
    await book.add({ key: 'k1', title: 'Duplicate', ingredients: [] });
  } catch (error) {
    duplicateError = error;
  }
  assert.ok(duplicateError instanceof Error);
  assert.deepStrictEqual(await book.get('k1'), beforeInvalid);

  let absentUpdateError;
  try {
    await book.update('missing', { title: 'Valid' });
  } catch (error) {
    absentUpdateError = error;
  }
  assert.ok(absentUpdateError instanceof Error);

  for (const operation of [
    () => book.add(null),
    () => book.add({ key: '', title: 'x', ingredients: [] }),
    () => book.add({ key: 'x', title: '   ', ingredients: [] }),
    () => book.add({ key: 'x', title: 'x', ingredients: [''] }),
    () => book.get(''),
    () => book.get(4),
    () => book.update('k1', null),
    () => book.update('k1', {}),
    () => book.update('', { title: 'x' }),
    () => book.remove('')
  ]) {
    await assert.rejects(operation, TypeError);
  }

  const sparseIngredients = new Array(1);
  assert.strictEqual(Object.hasOwn(sparseIngredients, 0), false);
  const sparseAddStart = events.length;
  let sparseAddError;
  try {
    await book.add({ key: 'sparse', title: 'Sparse', ingredients: sparseIngredients });
  } catch (error) {
    sparseAddError = error;
  }
  assert.ok(sparseAddError instanceof TypeError);
  assert.deepStrictEqual(events[sparseAddStart], { operation: 'add', phase: 'start' });
  assert.strictEqual(events[sparseAddStart + 1].operation, 'add');
  assert.strictEqual(events[sparseAddStart + 1].phase, 'failure');
  assert.strictEqual(events[sparseAddStart + 1].error, sparseAddError);
  assert.strictEqual(await book.get('sparse'), null);
  assert.strictEqual(Object.hasOwn(sparseIngredients, 0), false);

  const prefixThenHole = ['valid'];
  prefixThenHole.length = 2;
  assert.strictEqual(Object.hasOwn(prefixThenHole, 1), false);
  const sparseUpdateStart = events.length;
  let sparseUpdateError;
  try {
    await book.update('k1', { ingredients: prefixThenHole });
  } catch (error) {
    sparseUpdateError = error;
  }
  assert.ok(sparseUpdateError instanceof TypeError);
  assert.deepStrictEqual(events[sparseUpdateStart], { operation: 'update', phase: 'start' });
  assert.strictEqual(events[sparseUpdateStart + 1].operation, 'update');
  assert.strictEqual(events[sparseUpdateStart + 1].phase, 'failure');
  assert.strictEqual(events[sparseUpdateStart + 1].error, sparseUpdateError);
  assert.deepStrictEqual(await book.get('k1'), beforeInvalid);
  assert.deepStrictEqual(prefixThenHole[0], 'valid');
  assert.strictEqual(Object.hasOwn(prefixThenHole, 1), false);

  const whitespaceRecord = {
    key: '   ',
    title: ' Valid title ',
    ingredients: [' ', 'salt']
  };
  assert.deepStrictEqual(await book.add(whitespaceRecord), whitespaceRecord);
  whitespaceRecord.ingredients[0] = 'changed';
  assert.deepStrictEqual(await book.get('   '), {
    key: '   ',
    title: ' Valid title ',
    ingredients: [' ', 'salt']
  });
  assert.strictEqual(await book.remove('   '), true);

  assert.strictEqual(await book.remove('missing'), false);
  assert.strictEqual(await book.remove('k1'), true);
  assert.strictEqual(await book.remove('k1'), false);
  assert.strictEqual(await book.get('k1'), null);

  for (let i = 0; i < events.length; i += 2) {
    assert.strictEqual(events[i].phase, 'start');
    assert.ok(events[i + 1]);
    assert.ok(events[i + 1].phase === 'success' || events[i + 1].phase === 'failure');
    assert.strictEqual(events[i + 1].operation, events[i].operation);
  }

  let blockStarts = true;
  const startError = new Error('notification failed');
  const blocked = createRecipeBook(event => {
    if (blockStarts && event.phase === 'start') throw startError;
  });
  const blockedPromise = blocked.add({ key: 'x', title: 'X', ingredients: [] });
  assert.ok(blockedPromise instanceof Promise);
  await assert.rejects(blockedPromise, error => error === startError);
  blockStarts = false;
  assert.strictEqual(await blocked.get('x'), null);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

