const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['runStages']);
const { runStages } = api;

(async () => {
  const initial = { marker: true };
  const emptyPromise = runStages(initial, []);
  assert.ok(emptyPromise instanceof Promise);
  assert.strictEqual(await emptyPromise, initial);

  const calls = [];
  const stages = Object.freeze([
    function (value) {
      calls.push({ stage: 1, value, argc: arguments.length, receiver: this });
      return value + 2;
    },
    async function (value) {
      calls.push({ stage: 2, value, argc: arguments.length, receiver: this });
      await Promise.resolve();
      return value * 3;
    },
    function (value) {
      calls.push({ stage: 3, value, argc: arguments.length, receiver: this });
      return Promise.resolve(String(value));
    }
  ]);
  assert.strictEqual(await runStages(4, stages), '18');
  assert.deepStrictEqual(calls.map(call => [call.stage, call.value, call.argc]), [
    [1, 4, 1],
    [2, 6, 1],
    [3, 18, 1]
  ]);
  for (const call of calls) assert.strictEqual(call.receiver, undefined);
  assert.strictEqual(stages.length, 3);

  const order = [];
  const result = await runStages('x', [
    async value => {
      order.push('first-start');
      await new Promise(resolve => setTimeout(resolve, 5));
      order.push('first-end');
      return value + '1';
    },
    value => {
      order.push('second');
      return value + '2';
    }
  ]);
  assert.strictEqual(result, 'x12');
  assert.deepStrictEqual(order, ['first-start', 'first-end', 'second']);

  let invoked = 0;
  let validationPromise;
  assert.doesNotThrow(() => {
    validationPromise = runStages(0, [
      () => { invoked++; },
      null,
      () => { invoked++; }
    ]);
  });
  assert.ok(validationPromise instanceof Promise);
  await assert.rejects(validationPromise, TypeError);
  assert.strictEqual(invoked, 0);

  let nonArrayPromise;
  assert.doesNotThrow(() => {
    nonArrayPromise = runStages(0, 'not an array');
  });
  assert.ok(nonArrayPromise instanceof Promise);
  await assert.rejects(nonArrayPromise, TypeError);

  const sparseStages = new Array(1);
  assert.strictEqual(Object.hasOwn(sparseStages, 0), false);
  let sparsePromise;
  assert.doesNotThrow(() => {
    sparsePromise = runStages(0, sparseStages);
  });
  assert.ok(sparsePromise instanceof Promise);
  await assert.rejects(sparsePromise, TypeError);
  assert.strictEqual(Object.hasOwn(sparseStages, 0), false);

  const exactThrown = new Error('thrown');
  let laterCalls = 0;
  await assert.rejects(
    runStages(1, [
      () => { throw exactThrown; },
      () => { laterCalls++; }
    ]),
    error => error === exactThrown
  );
  assert.strictEqual(laterCalls, 0);

  const exactRejected = new Error('rejected');
  await assert.rejects(
    runStages(1, [
      () => Promise.reject(exactRejected),
      () => { laterCalls++; }
    ]),
    error => error === exactRejected
  );
  assert.strictEqual(laterCalls, 0);

  let once = 0;
  assert.strictEqual(await runStages(2, [value => {
    once++;
    return value;
  }]), 2);
  assert.strictEqual(once, 1);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

