import {
  LoadState,
  localizeMeta,
  loadLocalizedResource,
  type Dictionary,
  type DocumentMeta,
} from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function throwsTypeError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof TypeError, `${message}: expected TypeError`);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

const values = { name: 'Ada', count: 0 };
const titlePhrase = { key: 'title', values } as const;
const meta: DocumentMeta = {
  title: titlePhrase,
  summary: '',
};
const dictionary: Dictionary = {
  title: 'Hello {name}; {name} has {count} items and {missing}',
};

const localized = localizeMeta(meta, dictionary);
equal(localized.title, 'Hello Ada; Ada has 0 items and {missing}', 'tokens are replaced deterministically');
equal(localized.summary, '', 'empty literal phrases are preserved');
assert(Object.isFrozen(localized), 'localized metadata must be frozen');
assert(meta.title === titlePhrase, 'metadata phrase identity must not be changed');
equal(values.name, 'Ada', 'value maps must not be mutated');
equal(dictionary.title, 'Hello {name}; {name} has {count} items and {missing}', 'dictionary must not be mutated');

const fallback = localizeMeta(
  { title: { key: 'unknown', values: { x: 1 } }, summary: 'literal {x}' },
  {},
);
equal(fallback.title, 'unknown', 'a missing dictionary entry falls back to its key');
equal(fallback.summary, 'literal {x}', 'literal strings are not interpolated');

throwsTypeError(
  () => localizeMeta({ title: { key: '   ' }, summary: 'unused' }, {}),
  'blank localization keys are rejected synchronously',
);

async function expectRejection(
  promise: Promise<unknown>,
  constructor: typeof TypeError | typeof RangeError,
  message: string,
): Promise<void> {
  try {
    await promise;
  } catch (error) {
    assert(error instanceof constructor, `${message}: wrong exception type`);
    return;
  }
  throw new Error(`${message}: expected rejection`);
}

async function run(): Promise<void> {
  const invalidMeta: DocumentMeta = { title: { key: ' ' }, summary: 'unused' };
  const missingAddresses = { 1: '   ' } as unknown as Readonly<Record<number, string>>;
  const missing = await loadLocalizedResource(missingAddresses, 1, invalidMeta, {});
  equal(missing.state, LoadState.Missing, 'blank addresses are missing');
  equal(Object.keys(missing).length, 1, 'missing results contain only state');
  assert(Object.isFrozen(missing), 'missing results are frozen');

  const nonStringAddresses = { 2: 42 } as unknown as Readonly<Record<number, string>>;
  const nonString = await loadLocalizedResource(nonStringAddresses, 2, invalidMeta, {});
  equal(nonString.state, LoadState.Missing, 'non-string addresses are missing without localization');

  const absent = await loadLocalizedResource({}, 3, invalidMeta, {});
  equal(absent.state, LoadState.Missing, 'absent addresses are missing without localization');

  const addresses = { 0: '  resource://exact  ' };
  const readyPromise = loadLocalizedResource(addresses, 0, meta, dictionary);
  assert(readyPromise instanceof Promise, 'loading returns a Promise');
  const ready = await readyPromise;
  equal(ready.state, LoadState.Ready, 'valid addresses produce ready resources');
  equal(ready.address, '  resource://exact  ', 'valid addresses are retained exactly');
  assert(ready.meta !== undefined, 'ready resources contain metadata');
  equal(ready.meta.title, localized.title, 'ready resources contain localized metadata');
  assert(Object.isFrozen(ready), 'ready resources are frozen');
  assert(Object.isFrozen(ready.meta), 'ready metadata is frozen');
  equal(addresses[0], '  resource://exact  ', 'address maps are not mutated');

  let invalidMetaPromise: Promise<unknown>;
  try {
    invalidMetaPromise = loadLocalizedResource({ 4: 'resource://valid' }, 4, invalidMeta, {});
  } catch {
    throw new Error('metadata failures must settle through the returned Promise');
  }
  assert(invalidMetaPromise instanceof Promise, 'invalid metadata still produces a Promise');
  await expectRejection(invalidMetaPromise, TypeError, 'valid addresses localize and reject invalid metadata');

  for (const language of [-1, 1.5, Number.NaN]) {
    let returned: Promise<unknown>;
    try {
      returned = loadLocalizedResource({}, language, meta, dictionary);
    } catch {
      throw new Error('invalid languages must settle through the returned Promise');
    }
    assert(returned instanceof Promise, 'invalid-language calls still return a Promise');
    await expectRejection(returned, RangeError, `invalid language ${String(language)}`);
  }

  const largeLanguage = Number.MAX_SAFE_INTEGER + 1;
  const largeResult = await loadLocalizedResource({}, largeLanguage, meta, dictionary);
  equal(largeResult.state, LoadState.Missing, 'non-negative integers are valid without a safe-integer restriction');
  assert(Object.isFrozen(largeResult), 'large-language missing results are frozen');
}

void run();

