import { validateShipmentDraft } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function fields(result: ReturnType<typeof validateShipmentDraft>): string[] {
  if (result.error === null) throw new Error('expected an invalid result');
  for (const issue of result.error) {
    assert(typeof issue.field === 'string', 'issue field must be a string');
    assert(typeof issue.message === 'string', 'issue message must be a string');
  }
  return result.error.map((issue) => issue.field);
}

function sameStrings(actual: readonly string[], expected: readonly string[], message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}

const source = { recipientCode: '  AB-0042  ', crateCount: 1, priority: 'urgent' };
const valid = validateShipmentDraft(source);
assert(valid.error === null, 'valid input succeeds');
assert(valid.value !== undefined, 'valid input has a value');
equal(valid.value.recipientCode, 'AB-0042', 'recipient code is trimmed');
equal(valid.value.crateCount, 1, 'minimum crate count is accepted');
equal(valid.value.priority, 'urgent', 'urgent priority is accepted');
assert(valid.value !== source, 'the sanitized draft is a fresh object');
equal(source.recipientCode, '  AB-0042  ', 'input is not mutated');

const maximum = validateShipmentDraft({ recipientCode: 'ZZ-9999', crateCount: 500, priority: 'standard' });
assert(maximum.error === null, 'maximum crate count and standard priority are accepted');

const unknowns = validateShipmentDraft({
  recipientCode: 'AA-0000',
  crateCount: 10,
  priority: 'standard',
  zeta: true,
  alpha: true,
});
sameStrings(fields(unknowns), ['alpha', 'zeta'], 'unknown keys are reported first in lexical order');
assert(unknowns.value === undefined, 'invalid results have undefined value');

const malformedFields = validateShipmentDraft({
  recipientCode: 'aa-0001',
  crateCount: 0,
  priority: 'rush',
  extra: 1,
});
sameStrings(
  fields(malformedFields),
  ['extra', 'recipientCode', 'crateCount', 'priority'],
  'field validation follows deterministic order after unknown keys',
);

sameStrings(
  fields(validateShipmentDraft({ recipientCode: 'AA-0001', crateCount: 501, priority: 'standard' })),
  ['crateCount'],
  'crate counts above the maximum are rejected',
);
sameStrings(
  fields(validateShipmentDraft({ recipientCode: 'AA-0001', crateCount: 1.5, priority: 'standard' })),
  ['crateCount'],
  'fractional crate counts are rejected',
);
sameStrings(
  fields(validateShipmentDraft({ recipientCode: 'AA-0001', crateCount: Number.MAX_SAFE_INTEGER + 1, priority: 'standard' })),
  ['crateCount'],
  'unsafe integers are rejected',
);

sameStrings(fields(validateShipmentDraft({})), ['recipientCode', 'crateCount', 'priority'], 'all missing fields are reported');
sameStrings(fields(validateShipmentDraft(null)), ['$'], 'null is rejected without field inspection');
sameStrings(fields(validateShipmentDraft([])), ['$'], 'arrays are rejected without field inspection');
sameStrings(fields(validateShipmentDraft(Object.create(null))), ['$'], 'null-prototype objects are rejected');
sameStrings(fields(validateShipmentDraft(Object.create({ recipientCode: 'AA-0001' }))), ['$'], 'custom prototypes are rejected');

const requiredFields = ['recipientCode', 'crateCount', 'priority'] as const;
const requiredValues: Readonly<Record<(typeof requiredFields)[number], unknown>> = {
  recipientCode: 'CD-1234',
  crateCount: 2,
  priority: 'standard',
};
for (const field of requiredFields) {
  const draft: Record<string, unknown> = {
    recipientCode: 'CD-1234',
    crateCount: 2,
    priority: 'standard',
  };
  Object.defineProperty(draft, field, {
    value: requiredValues[field],
    enumerable: false,
    configurable: true,
  });
  const result = validateShipmentDraft(draft);
  sameStrings(fields(result), [field], `non-enumerable required field ${field} is treated as missing`);
  assert(result.value === undefined, `non-enumerable required field ${field} produces no value`);
}

const withHiddenExtra: Record<string, unknown> = {
  recipientCode: 'CD-1234',
  crateCount: 2,
  priority: 'standard',
};
Object.defineProperty(withHiddenExtra, 'hidden', { value: 'ignored', enumerable: false });
assert(validateShipmentDraft(withHiddenExtra).error === null, 'non-enumerable extra properties are outside the key set');

const mutable = { recipientCode: ' EF-5678 ', crateCount: 3, priority: 'urgent' };
const detached = validateShipmentDraft(mutable);
assert(detached.error === null && detached.value !== undefined, 'copy-isolation input starts valid');
mutable.recipientCode = 'XX-0000';
mutable.crateCount = 99;
equal(detached.value.recipientCode, 'EF-5678', 'result does not retain recipient input state');
equal(detached.value.crateCount, 3, 'result does not retain numeric input state');

