export interface AccountRecord { readonly id: string; readonly email: string }
export interface ValidationIssue { readonly field: string; readonly message: string }

const own = (value: object, key: string): boolean => Object.prototype.hasOwnProperty.call(value, key);
const nonblank = (value: unknown): value is string => typeof value === 'string' && value.trim().length > 0;
const emailPattern = /^[^@\s]+@[^@\s.]+(?:\.[^@\s.]+)+$/;

export function validateAccount(
  method: 'CREATE' | 'UPDATE',
  body: Readonly<Record<string, unknown>>,
  accounts: readonly AccountRecord[],
  currentId?: string,
): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const checkText = (field: string, required: boolean): boolean => {
    if (!own(body, field)) {
      if (required) issues.push({ field, message: `${field} is required` });
      return false;
    }
    if (!nonblank(body[field])) {
      issues.push({ field, message: `${field} must be a non-empty string` });
      return false;
    }
    return true;
  };

  if (method === 'CREATE') {
    checkText('displayName', true);
    checkText('secret', true);
  } else {
    checkText('displayName', false);
  }

  let duplicateEmail = false;
  const validEmailText = checkText('email', method === 'CREATE');
  if (validEmailText) {
    const email = (body.email as string).trim();
    if (!emailPattern.test(email)) {
      issues.push({ field: 'email', message: 'email is invalid' });
    } else {
      duplicateEmail = accounts.some(account =>
        (method !== 'UPDATE' || account.id !== currentId) &&
        account.email.trim().toLowerCase() === email.toLowerCase()
      );
    }
  }

  if (method === 'UPDATE') checkText('accessLevel', false);
  if (duplicateEmail) {
    issues.push({ field: 'email', message: 'Email is already in use' });
  }
  return issues;
}

