import { validateAccount, type AccountRecord } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function issueFields(issues: ReturnType<typeof validateAccount>): string[] {
  for (const issue of issues) {
    assert(typeof issue.field === 'string', 'issue fields are strings');
    assert(typeof issue.message === 'string', 'issue messages are strings');
  }
  return issues.map((issue) => issue.field);
}

function same(actual: readonly string[], expected: readonly string[], message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}

const accounts = [
  { id: 'one', email: ' First@Example.com ' },
  { id: 'two', email: 'second@example.com' },
] as unknown as readonly AccountRecord[];

const createValid = validateAccount(
  'CREATE',
  { displayName: '  Ada  ', secret: ' x ', email: 'new@example.com', ignored: 1 },
  accounts,
);
equal(createValid.length, 0, 'a valid CREATE succeeds and unknown properties are ignored');

same(
  issueFields(validateAccount('CREATE', {}, accounts)),
  ['displayName', 'secret', 'email'],
  'CREATE required fields are reported in order',
);
same(
  issueFields(validateAccount('CREATE', { displayName: ' ', secret: 12, email: 'a@@b.com' }, accounts)),
  ['displayName', 'secret', 'email'],
  'CREATE reports at most one format or required issue per field',
);

const duplicateCreate = validateAccount(
  'CREATE',
  { displayName: 'Name', secret: 'secret', email: ' first@example.COM ' },
  accounts,
);
equal(duplicateCreate.length, 1, 'CREATE detects a case-insensitive trimmed duplicate');
equal(duplicateCreate[0].field, 'email', 'duplicate issue belongs to email');
equal(duplicateCreate[0].message, 'Email is already in use', 'duplicate message is exact');

for (const email of ['a@b.c', 'local.part@sub.example.com']) {
  equal(
    validateAccount('CREATE', { displayName: 'N', secret: 'S', email }, [], undefined).length,
    0,
    `${email} is well formed`,
  );
}
for (const email of ['@b.com', 'a@', 'a@b', 'a@.com', 'a@b.', 'a@b..com', 'a@@b.com']) {
  same(
    issueFields(validateAccount('CREATE', { displayName: 'N', secret: 'S', email }, [])),
    ['email'],
    `${email} is malformed`,
  );
}

const emptyUpdate = validateAccount('UPDATE', { unknown: true }, accounts, 'one');
equal(emptyUpdate.length, 0, 'an UPDATE with no recognized properties is valid');

const inheritedOnly = Object.create({
  displayName: ' ',
  email: 'first@example.com',
  accessLevel: '',
}) as Readonly<Record<string, unknown>>;
equal(
  validateAccount('UPDATE', inheritedOnly, accounts).length,
  0,
  'inherited recognized properties are not treated as provided',
);

same(
  issueFields(validateAccount('UPDATE', { accessLevel: ' ', email: undefined, displayName: 3 }, accounts)),
  ['displayName', 'email', 'accessLevel'],
  'provided UPDATE fields are validated in fixed order',
);

const selfUpdate = validateAccount('UPDATE', { email: ' FIRST@example.com ' }, accounts, 'one');
equal(selfUpdate.length, 0, 'the current account is excluded during UPDATE');
const withoutCurrentId = validateAccount('UPDATE', { email: ' FIRST@example.com ' }, accounts);
equal(withoutCurrentId.length, 1, 'omitting currentId excludes no account');
equal(withoutCurrentId[0].message, 'Email is already in use', 'omitted-currentId duplicate is reported');

const reordered = [accounts[1], accounts[0]] as readonly AccountRecord[];
const duplicateA = validateAccount('UPDATE', { email: 'second@example.com' }, accounts, 'one');
const duplicateB = validateAccount('UPDATE', { email: 'second@example.com' }, reordered, 'one');
equal(JSON.stringify(duplicateA), JSON.stringify(duplicateB), 'account order does not affect output');

const mixedIssuesA = validateAccount(
  'UPDATE',
  { email: 'a@b.com', accessLevel: '' },
  [{ id: 'other', email: 'a@b.com' }] as readonly AccountRecord[],
  'current',
);
const mixedIssuesB = validateAccount(
  'UPDATE',
  { email: 'a@b.com', accessLevel: '' },
  [{ id: 'unrelated', email: 'elsewhere@example.com' }, { id: 'other', email: 'a@b.com' }] as readonly AccountRecord[],
  'current',
);
same(issueFields(mixedIssuesA), ['accessLevel', 'email'], 'field issues precede an appended duplicate-email issue');
equal(mixedIssuesA[1].message, 'Email is already in use', 'the appended duplicate message is exact');
equal(JSON.stringify(mixedIssuesA), JSON.stringify(mixedIssuesB), 'account ordering and unrelated accounts do not change issue order');

const body = { displayName: 'Original', secret: 'Secret', email: 'fresh@example.com' };
const first = validateAccount('CREATE', body, accounts);
const second = validateAccount('CREATE', body, accounts);
assert(first !== second, 'each call returns a fresh issue array');
equal(body.displayName, 'Original', 'body is not mutated');
equal((accounts[0] as unknown as { email: string }).email, ' First@Example.com ', 'accounts are not mutated');

