import { createStyleRegistry, type ColorScheme, type StyleObject } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function jsonEqual(actual: unknown, expected: unknown, message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}

function throwsTypeError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof TypeError, `${message}: expected TypeError`);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

const nested = { foreground: '#fff', opacity: 0.5, enabled: true, reset: null };
const scheme: ColorScheme = { palette: { primary: nested, empty: {} } };
const rules: StyleObject = { button: { padding: 0, state: { visible: false } }, label: 'plain' };
const registry = createStyleRegistry(scheme, rules);

nested.foreground = '#000';
(rules.button as { padding: number }).padding = 99;
const storedScheme = registry.getScheme();
const storedRules = registry.getRules();
equal((storedScheme.palette.primary as { foreground: string }).foreground, '#fff', 'scheme is copied immediately');
equal((storedRules.button as { padding: number }).padding, 0, 'rules are copied immediately');

const schemeAgain = registry.getScheme();
const rulesAgain = registry.getRules();
assert(storedScheme !== schemeAgain, 'getScheme returns a fresh outer object');
assert(storedScheme.palette !== schemeAgain.palette, 'getScheme deeply copies the palette');
assert(storedRules !== rulesAgain, 'getRules returns a fresh outer object');
assert(storedRules.button !== rulesAgain.button, 'getRules deeply copies nested objects');

(storedScheme.palette.primary as { foreground: string }).foreground = 'changed';
(storedRules.button as { state: { visible: boolean } }).state.visible = true;
equal(
  (registry.getScheme().palette.primary as { foreground: string }).foreground,
  '#fff',
  'mutating a scheme result does not affect stored state',
);
equal(
  (registry.getRules().button as { state: { visible: boolean } }).state.visible,
  false,
  'mutating a rules result does not affect stored state',
);

const nullPrototype = Object.create(null) as Record<string, unknown>;
nullPrototype.first = 'one';
nullPrototype.second = { value: 2 };
const nullRegistry = createStyleRegistry(
  { palette: nullPrototype as StyleObject },
  Object.create(null) as StyleObject,
);
jsonEqual(nullRegistry.getScheme().palette, { first: 'one', second: { value: 2 } }, 'null-prototype objects are accepted and copied');
jsonEqual(nullRegistry.getRules(), {}, 'empty objects are valid');
equal(Object.keys(nullRegistry.getScheme().palette).join(','), 'first,second', 'property insertion order is preserved');

const protoPalette = Object.create(null) as Record<string, unknown>;
Object.defineProperty(protoPalette, '__proto__', {
  value: 'retain',
  enumerable: true,
  writable: true,
  configurable: true,
});
const protoNested = Object.create(null) as Record<string, unknown>;
Object.defineProperty(protoNested, '__proto__', {
  value: 'nested-retain',
  enumerable: true,
  writable: true,
  configurable: true,
});
const protoRules = Object.create(null) as Record<string, unknown>;
protoRules.container = protoNested;
const protoRegistry = createStyleRegistry(
  { palette: protoPalette as StyleObject },
  protoRules as StyleObject,
);
protoPalette.__proto__ = 'changed-original';
protoNested.__proto__ = 'changed-original';
const copiedProtoScheme = protoRegistry.getScheme();
const copiedProtoRules = protoRegistry.getRules();
assert(Object.prototype.hasOwnProperty.call(copiedProtoScheme.palette, '__proto__'), 'palette retains an own __proto__ property');
equal(copiedProtoScheme.palette.__proto__, 'retain', 'palette retains the exact __proto__ value');
const copiedContainer = copiedProtoRules.container as StyleObject;
assert(Object.prototype.hasOwnProperty.call(copiedContainer, '__proto__'), 'nested rules retain an own __proto__ property');
equal(copiedContainer.__proto__, 'nested-retain', 'nested rules retain the exact __proto__ value');
(copiedProtoScheme.palette as Record<string, unknown>).__proto__ = 'changed-result';
(copiedContainer as Record<string, unknown>).__proto__ = 'changed-result';
equal(protoRegistry.getScheme().palette.__proto__, 'retain', 'mutating a returned __proto__ value does not affect stored palette data');
equal(
  (protoRegistry.getRules().container as StyleObject).__proto__,
  'nested-retain',
  'mutating a returned nested __proto__ value does not affect stored rules',
);

const hiddenLeaf: Record<string, unknown> = {};
Object.defineProperty(hiddenLeaf, 'concealed', { value: 7, enumerable: false });
const hiddenRules: Record<string, unknown> = {};
Object.defineProperty(hiddenRules, 'hiddenBranch', { value: hiddenLeaf, enumerable: false });
const hiddenRegistry = createStyleRegistry({ palette: {} }, hiddenRules as StyleObject);
const hiddenCopy = hiddenRegistry.getRules() as Record<string, unknown>;
assert(Object.prototype.hasOwnProperty.call(hiddenCopy, 'hiddenBranch'), 'non-enumerable own string keys are copied');
const hiddenBranch = hiddenCopy.hiddenBranch as Record<string, unknown>;
assert(Object.prototype.hasOwnProperty.call(hiddenBranch, 'concealed'), 'nested non-enumerable own string keys are copied');
equal(hiddenBranch.concealed, 7, 'non-enumerable accepted values survive deep copies');

const marker = Symbol('ignored');
const symbolRules = { visible: true } as Record<PropertyKey, unknown>;
symbolRules[marker] = () => 'outside model';
const symbolRegistry = createStyleRegistry({ palette: {} }, symbolRules as StyleObject);
equal(Object.getOwnPropertySymbols(symbolRegistry.getRules()).length, 0, 'symbol properties are not copied');

const malformedValues: unknown[] = [
  [],
  Number.NaN,
  Number.POSITIVE_INFINITY,
  Number.NEGATIVE_INFINITY,
  undefined,
  () => 1,
  Symbol('value'),
  1n,
  new Date(0),
  Object.create({ inherited: true }),
];
for (const value of malformedValues) {
  throwsTypeError(
    () => createStyleRegistry({ palette: { bad: value } as unknown as StyleObject }, {}),
    `malformed palette value ${String(value)}`,
  );
  throwsTypeError(
    () => createStyleRegistry({ palette: {} }, { nested: { bad: value } } as unknown as StyleObject),
    `malformed nested rule value ${String(value)}`,
  );
}

throwsTypeError(
  () => createStyleRegistry({ palette: { valid: 'yes', bad: Infinity } as unknown as StyleObject }, rules),
  'all data is validated during construction',
);
equal((rules.button as { padding: number }).padding, 99, 'failed validation does not mutate inputs');

