Implement a new TypeScript module with this API:

```typescript
export interface Charge {
  id: string;
  accountId: string;
  day: string;
  amount: number;
}

export function filterCharges(
  charges: readonly Charge[],
  accountId: string,
  fromDay: string,
  toDay: string
): Charge[];
```

Days must use the exact Gregorian `YYYY-MM-DD` format and represent real calendar dates. IDs and account IDs must be non-empty strings. Amounts must be finite and non-negative. Validate every supplied charge, including records belonging to other accounts, and throw `TypeError` for malformed records or arguments. Throw `RangeError` when `fromDay` is later than `toDay`. Return fresh copies of records whose account ID exactly matches and whose day lies within the inclusive range. Preserve input order, return an empty array when nothing matches, and never mutate or alias the input.

Return only the complete source file; do not include Markdown fences or prose.

export interface Charge {
  id: string;
  accountId: string;
  day: string;
  amount: number;
}

function parseDay(value: string): number {
  if (typeof value !== "string") {
    throw new TypeError("Day must be a string");
  }
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (match === null) {
    throw new TypeError("Invalid day");
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (year === 0 || month < 1 || month > 12) {
    throw new TypeError("Invalid day");
  }
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) {
    throw new TypeError("Invalid day");
  }
  return year * 10000 + month * 100 + day;
}

function requireText(value: unknown): asserts value is string {
  if (typeof value !== "string" || value.length === 0) {
    throw new TypeError("Expected a non-empty string");
  }
}

export function filterCharges(
  charges: readonly Charge[],
  accountId: string,
  fromDay: string,
  toDay: string
): Charge[] {
  if (!Array.isArray(charges)) {
    throw new TypeError("Charges must be an array");
  }
  requireText(accountId);
  const from = parseDay(fromDay);
  const to = parseDay(toDay);
  if (from > to) {
    throw new RangeError("Invalid day range");
  }

  const result: Charge[] = [];
  for (let index = 0; index < charges.length; index += 1) {
    if (!Object.prototype.hasOwnProperty.call(charges, index)) {
      throw new TypeError("Invalid charge");
    }
    const charge = charges[index] as Charge;
    if ((typeof charge !== "object" && typeof charge !== "function") || charge === null) {
      throw new TypeError("Invalid charge");
    }
    requireText(charge.id);
    requireText(charge.accountId);
    const time = parseDay(charge.day);
    if (!Number.isFinite(charge.amount) || charge.amount < 0) {
      throw new TypeError("Invalid amount");
    }
    if (charge.accountId === accountId && time >= from && time <= to) {
      result.push({
        id: charge.id,
        accountId: charge.accountId,
        day: charge.day,
        amount: charge.amount,
      });
    }
  }
  return result;
}

