import { filterCharges, type Charge } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function throws(
  constructor: typeof TypeError | typeof RangeError,
  action: () => unknown,
  message: string,
): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof constructor, `${message}: wrong exception type`);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

const charges: Charge[] = [
  { id: 'before', accountId: 'acct', day: '2024-02-28', amount: 0 },
  { id: 'leap', accountId: 'acct', day: '2024-02-29', amount: Number.MAX_VALUE },
  { id: 'other', accountId: 'other', day: '2024-03-01', amount: 3 },
  { id: 'end', accountId: 'acct', day: '2024-03-01', amount: 4.5 },
  { id: 'after', accountId: 'acct', day: '2024-03-02', amount: 5 },
];
const result = filterCharges(charges, 'acct', '2024-02-29', '2024-03-01');
equal(result.map((charge) => charge.id).join(','), 'leap,end', 'matching records are returned in input order with inclusive boundaries');
assert(result[0] !== charges[1], 'returned records are fresh copies');
result[0].amount = 1;
equal(charges[1].amount, Number.MAX_VALUE, 'mutating a result does not affect input records');
equal(charges.length, 5, 'the input array is not mutated');

equal(filterCharges(charges, 'missing', '2024-01-01', '2024-12-31').length, 0, 'no matches returns an empty array');
equal(filterCharges([], 'acct', '0099-01-01', '0099-01-01').length, 0, 'four-digit years below 100 are accepted');

const earlyCharge: Charge = { id: 'early', accountId: 'acct', day: '0099-01-01', amount: 2 };
const earlyResult = filterCharges([earlyCharge], 'acct', '0099-01-01', '0099-01-01');
equal(earlyResult.length, 1, 'a matching year 0099 charge is included');
assert(earlyResult[0] !== earlyCharge, 'the year 0099 record is copied');
equal(earlyResult[0].id, 'early', 'the copied id is complete');
equal(earlyResult[0].accountId, 'acct', 'the copied accountId is complete');
equal(earlyResult[0].day, '0099-01-01', 'the copied day is complete');
equal(earlyResult[0].amount, 2, 'the copied amount is complete');

const whitespaceIds: Charge[] = [{ id: ' ', accountId: ' ', day: '2000-02-29', amount: -0 }];
equal(filterCharges(whitespaceIds, ' ', '2000-02-29', '2000-02-29').length, 1, 'non-empty strings and negative zero are accepted');

const hiddenIdRecord: Record<string, unknown> = {
  accountId: 'acct',
  day: '2024-01-01',
  amount: 6,
};
Object.defineProperty(hiddenIdRecord, 'id', { value: 'hidden-id', enumerable: false });
const hiddenIdResult = filterCharges(
  [hiddenIdRecord as unknown as Charge],
  'acct',
  '2024-01-01',
  '2024-01-01',
);
equal(hiddenIdResult.length, 1, 'a valid non-enumerable required property is read');
equal(hiddenIdResult[0].id, 'hidden-id', 'the copied result preserves a non-enumerable id value');
equal(hiddenIdResult[0].accountId, 'acct', 'the copied hidden-id record includes accountId');
equal(hiddenIdResult[0].day, '2024-01-01', 'the copied hidden-id record includes day');
equal(hiddenIdResult[0].amount, 6, 'the copied hidden-id record includes amount');

const invalidDays = [
  '2024-2-29',
  '24-02-29',
  '2024-02-30',
  '2023-02-29',
  '1900-02-29',
  '2024-00-01',
  '2024-01-00',
  '2024-13-01',
  '2024-01-01x',
];
for (const day of invalidDays) {
  throws(TypeError, () => filterCharges([], 'acct', day, '2024-12-31'), `invalid fromDay ${day}`);
  throws(TypeError, () => filterCharges([], 'acct', '2024-01-01', day), `invalid toDay ${day}`);
}
throws(RangeError, () => filterCharges([], 'acct', '2024-03-01', '2024-02-29'), 'reversed ranges are rejected');

for (const accountId of ['', 1 as unknown as string]) {
  throws(TypeError, () => filterCharges([], accountId, '2024-01-01', '2024-01-01'), 'malformed accountId arguments are rejected');
}

const base: Charge = { id: 'ok', accountId: 'acct', day: '2024-01-01', amount: 1 };
const malformedRecords: unknown[] = [
  null,
  { ...base, id: '' },
  { ...base, id: 4 },
  { ...base, accountId: '' },
  { ...base, accountId: null },
  { ...base, day: '2024-04-31' },
  { ...base, amount: -1 },
  { ...base, amount: Number.NaN },
  { ...base, amount: Number.POSITIVE_INFINITY },
  { ...base, amount: '1' },
];
for (const record of malformedRecords) {
  throws(
    TypeError,
    () => filterCharges([record] as unknown as readonly Charge[], 'acct', '2024-01-01', '2024-12-31'),
    `malformed charge ${String(record)}`,
  );
}

throws(
  TypeError,
  () => filterCharges({} as unknown as readonly Charge[], 'acct', '2024-01-01', '2024-12-31'),
  'a non-array charges argument is rejected',
);
throws(
  TypeError,
  () => filterCharges(
    [base, { ...base, accountId: 'other', amount: Infinity }],
    'acct',
    '2024-01-01',
    '2024-12-31',
  ),
  'every supplied charge is validated even when another record already matches',
);
throws(
  TypeError,
  () => filterCharges(
    [{ ...base, accountId: 'other', day: 'not-a-day' }],
    'acct',
    '2024-01-01',
    '2024-12-31',
  ),
  'charges belonging to other accounts are validated',
);

const sparse: Charge[] = [{ ...base }];
sparse.length = 2;
throws(
  TypeError,
  () => filterCharges(sparse, 'acct', '2024-01-01', '2024-12-31'),
  'a trailing array hole is a malformed supplied entry',
);
equal(sparse.length, 2, 'validating a sparse array does not change its length');
equal(sparse[0].id, 'ok', 'validating a sparse array does not mutate existing records');
assert(!(1 in sparse), 'validating a sparse array does not fill its hole');

