import { FeatureCatalog } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function throwsMessage(action: () => unknown, expected: string, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof Error, `${message}: expected Error`);
    equal(error.message, expected, message);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

const catalog = new FeatureCatalog();
equal(catalog.snapshot().length, 0, 'a new catalog is empty');

catalog.insert('  beta  ', 'second');
catalog.insert('Alpha', undefined, false);
catalog.insert('alpha', 'lowercase');
const initial = catalog.snapshot();
equal(initial.map((item) => item.code).join(','), 'Alpha,alpha,beta', 'snapshots use ordinary string ordering and normalized codes');
equal(initial[0].active, false, 'an explicitly inserted false state is retained');
equal(initial[1].active, true, 'active defaults to true');
equal(initial[2].note, 'second', 'notes are retained');

throwsMessage(() => catalog.insert('beta'), 'Feature already exists', 'duplicate normalized codes are rejected');
throwsMessage(() => catalog.insert('   '), 'Feature code must not be empty', 'blank codes are rejected');
throwsMessage(() => catalog.insert(''), 'Feature code must not be empty', 'empty codes are rejected');

catalog.amend(' beta ', { active: false });
let beta = catalog.snapshot().find((item) => item.code === 'beta');
assert(beta !== undefined, 'beta exists after amendment');
equal(beta.active, false, 'amend applies an explicitly supplied false');
equal(beta.note, 'second', 'an absent patch field remains unchanged');

catalog.amend('beta', { note: 'changed' });
beta = catalog.snapshot().find((item) => item.code === 'beta');
assert(beta !== undefined, 'beta remains present');
equal(beta.note, 'changed', 'amend changes a supplied note');
equal(beta.active, false, 'amending note leaves active unchanged');

const beforeInvalidAmend = JSON.stringify(catalog.snapshot());
throwsMessage(
  () => catalog.amend(' ', { active: false }),
  'Feature code must not be empty',
  'amend rejects a blank normalized code',
);
equal(JSON.stringify(catalog.snapshot()), beforeInvalidAmend, 'a rejected blank amend leaves the catalog unchanged');

const beforeInvalidDrop = JSON.stringify(catalog.snapshot());
throwsMessage(
  () => catalog.drop('\t'),
  'Feature code must not be empty',
  'drop rejects a horizontal-tab code',
);
equal(JSON.stringify(catalog.snapshot()), beforeInvalidDrop, 'a rejected tab-only drop leaves the catalog unchanged');

const detached = catalog.snapshot();
const detachedBeta = detached.find((item) => item.code === 'beta');
assert(detachedBeta !== undefined, 'detached snapshot contains beta');
detachedBeta.code = 'mutated';
detachedBeta.note = 'mutated';
detachedBeta.active = true;
beta = catalog.snapshot().find((item) => item.code === 'beta');
assert(beta !== undefined, 'catalog still contains beta after snapshot mutation');
equal(beta.note, 'changed', 'snapshot records cannot mutate catalog state');
equal(beta.active, false, 'snapshot boolean mutation is isolated');

throwsMessage(() => catalog.amend('missing', { active: true }), 'Feature not found', 'amending a missing feature fails');
throwsMessage(() => catalog.drop('missing'), 'Feature not found', 'dropping a missing feature fails');

catalog.drop(' beta ');
equal(catalog.snapshot().map((item) => item.code).join(','), 'Alpha,alpha', 'drop uses normalized code and removes only the target');
throwsMessage(() => catalog.drop('beta'), 'Feature not found', 'a removed feature cannot be removed twice');

catalog.drop('Alpha');
equal(catalog.snapshot().map((item) => item.code).join(','), 'alpha', 'code identity remains case-sensitive');

