import math
import sys
import unittest
from collections import UserDict
from fractions import Fraction
from types import MappingProxyType

from solution import aggregate_metrics


class AggregateMetricsTests(unittest.TestCase):
    def test_normal_aggregation_order_count_and_total(self):
        events = [
            {"category": "ignored", "amount": 100, "accepted": False},
            {"category": "beta", "amount": 3, "accepted": True},
            {"category": "alpha", "amount": 2.5, "accepted": True},
            {"category": "beta", "amount": 4, "accepted": True},
            {"category": "alpha", "amount": 999, "accepted": False},
        ]
        self.assertEqual(
            aggregate_metrics(events),
            [
                {"category": "beta", "count": 2, "total": 7},
                {"category": "alpha", "count": 1, "total": 2.5},
            ],
        )

    def test_empty_and_entirely_rejected_inputs(self):
        self.assertEqual(aggregate_metrics([]), [])
        self.assertEqual(
            aggregate_metrics([
                {"category": "a", "amount": 1, "accepted": False},
                {"category": "b", "amount": Fraction(3, 7), "accepted": False},
            ]),
            [],
        )

    def test_first_accepted_appearance_controls_category_order(self):
        events = [
            {"category": "second", "amount": 1, "accepted": False},
            {"category": "first", "amount": 2, "accepted": True},
            {"category": "second", "amount": 3, "accepted": True},
            {"category": "first", "amount": 4, "accepted": True},
        ]
        result = aggregate_metrics(events)
        self.assertEqual([row["category"] for row in result], ["first", "second"])

    def test_accepts_general_iterables_and_mapping_implementations(self):
        events = iter([
            UserDict({"category": "user", "amount": 2, "accepted": True}),
            MappingProxyType({"category": "proxy", "amount": 3, "accepted": True}),
        ])
        self.assertEqual(
            aggregate_metrics(events),
            [
                {"category": "user", "count": 1, "total": 2},
                {"category": "proxy", "count": 1, "total": 3},
            ],
        )

    def test_arbitrary_precision_integers_remain_exact(self):
        huge = 10 ** 500
        result = aggregate_metrics([
            {"category": "huge", "amount": huge, "accepted": True},
            {"category": "huge", "amount": huge, "accepted": True},
        ])
        self.assertEqual(
            result,
            [{"category": "huge", "count": 2, "total": 2 * huge}],
        )
        self.assertIs(type(result[0]["total"]), int)

    def test_arbitrary_precision_integer_cancellation_remains_exact(self):
        huge = 10 ** 500
        result = aggregate_metrics([
            {"category": "huge", "amount": huge, "accepted": True},
            {"category": "huge", "amount": -huge, "accepted": True},
            {"category": "huge", "amount": 7, "accepted": True},
        ])
        self.assertEqual(
            result,
            [{"category": "huge", "count": 3, "total": 7}],
        )
        self.assertIs(type(result[0]["total"]), int)

    def test_rejected_arbitrary_precision_integer_contributes_nothing(self):
        huge = 10 ** 500
        result = aggregate_metrics([
            {"category": "x", "amount": huge, "accepted": False},
            {"category": "x", "amount": 3, "accepted": True},
        ])
        self.assertEqual(result, [{"category": "x", "count": 1, "total": 3}])

    def test_fraction_totals_remain_exact(self):
        result = aggregate_metrics([
            {"category": "ratio", "amount": Fraction(1, 3), "accepted": True},
            {"category": "ratio", "amount": Fraction(1, 6), "accepted": True},
            {"category": "ratio", "amount": 2, "accepted": True},
        ])
        self.assertEqual(result[0]["total"], Fraction(5, 2))
        self.assertIsInstance(result[0]["total"], Fraction)

    def test_finite_float_inputs_may_sum_to_infinity(self):
        largest = sys.float_info.max
        result = aggregate_metrics([
            {"category": "overflowed-total", "amount": largest, "accepted": True},
            {"category": "overflowed-total", "amount": largest, "accepted": True},
        ])
        self.assertEqual(result[0]["count"], 2)
        self.assertTrue(math.isinf(result[0]["total"]))
        self.assertGreater(result[0]["total"], 0)

    def test_native_accepted_event_addition_order_is_preserved(self):
        result = aggregate_metrics([
            {"category": "ordered", "amount": 1e16, "accepted": True},
            {"category": "ordered", "amount": -1e16, "accepted": True},
            {"category": "ordered", "amount": 1.0, "accepted": True},
        ])
        self.assertEqual(result[0]["total"], 1.0)

    def test_native_mixed_type_overflow_propagates(self):
        events = [
            {"category": "mixed", "amount": Fraction(10 ** 500, 1), "accepted": True},
            {"category": "mixed", "amount": 1.0, "accepted": True},
        ]
        with self.assertRaises(OverflowError):
            aggregate_metrics(events)

    def test_nonfinite_float_is_invalid_even_when_rejected(self):
        for amount in (float("nan"), float("inf"), float("-inf")):
            with self.subTest(amount=amount):
                with self.assertRaises(ValueError):
                    aggregate_metrics([
                        {"category": "x", "amount": amount, "accepted": False}
                    ])

    def test_boolean_and_non_real_amounts_are_rejected(self):
        for amount in (True, False, 1 + 2j, "3", None):
            with self.subTest(amount=amount):
                with self.assertRaises(TypeError):
                    aggregate_metrics([
                        {"category": "x", "amount": amount, "accepted": True}
                    ])

    def test_accepted_must_be_exact_boolean(self):
        for accepted in (0, 1, None, "yes"):
            with self.subTest(accepted=accepted):
                with self.assertRaises(TypeError):
                    aggregate_metrics([
                        {"category": "x", "amount": 1, "accepted": accepted}
                    ])

    def test_category_type_and_empty_category_validation(self):
        for category in (1, None, b"x"):
            with self.subTest(category=category):
                with self.assertRaises(TypeError):
                    aggregate_metrics([
                        {"category": category, "amount": 1, "accepted": True}
                    ])
        with self.assertRaises(ValueError):
            aggregate_metrics([
                {"category": "", "amount": 1, "accepted": True}
            ])

    def test_nonempty_whitespace_category_is_not_normalized(self):
        self.assertEqual(
            aggregate_metrics([
                {"category": " ", "amount": 1, "accepted": True}
            ]),
            [{"category": " ", "count": 1, "total": 1}],
        )

    def test_missing_and_unexpected_keys_raise_value_error(self):
        invalid_events = [
            {"category": "x", "amount": 1},
            {"category": "x", "amount": 1, "accepted": True, "extra": 2},
            {},
        ]
        for event in invalid_events:
            with self.subTest(event=event):
                with self.assertRaises(ValueError):
                    aggregate_metrics([event])

    def test_non_mapping_events_raise_type_error(self):
        for event in (None, 3, ("category", "x"), ["category", "x"]):
            with self.subTest(event=event):
                with self.assertRaises(TypeError):
                    aggregate_metrics([event])

    def test_outer_input_must_be_non_string_iterable(self):
        for events in ("events", b"events", 42, None):
            with self.subTest(events=events):
                with self.assertRaises(TypeError):
                    aggregate_metrics(events)

    def test_invalid_late_event_prevents_a_result(self):
        events = [
            {"category": "valid", "amount": 5, "accepted": True},
            {"category": "invalid", "amount": float("inf"), "accepted": False},
        ]
        with self.assertRaises(ValueError):
            aggregate_metrics(events)

    def test_huge_rejected_value_does_not_hide_later_malformed_event(self):
        events = [
            {"category": "huge", "amount": 10 ** 500, "accepted": False},
            {"category": "", "amount": 2, "accepted": False},
        ]
        with self.assertRaises(ValueError):
            aggregate_metrics(events)

    def test_inputs_are_not_mutated_and_outputs_do_not_alias_them(self):
        events = [{"category": "a", "amount": 2, "accepted": True}]
        original_event = dict(events[0])
        result = aggregate_metrics(events)
        self.assertEqual(events, [original_event])

        events[0]["amount"] = 100
        events.append({"category": "b", "amount": 4, "accepted": True})
        self.assertEqual(result, [{"category": "a", "count": 1, "total": 2}])

        result[0]["category"] = "changed"
        self.assertEqual(events[0]["category"], "a")

    def test_each_call_returns_fresh_list_and_result_dictionaries(self):
        events = [{"category": "a", "amount": 2, "accepted": True}]
        first = aggregate_metrics(events)
        second = aggregate_metrics(events)
        self.assertIsNot(first, second)
        self.assertIsNot(first[0], second[0])

        first.append({"category": "extra", "count": 0, "total": 0})
        first[0]["total"] = 999
        self.assertEqual(second, [{"category": "a", "count": 1, "total": 2}])


if __name__ == "__main__":
    unittest.main()

