#[path = "solution.rs"]
mod solution;

use solution::{project_slug, qualified_ref, RepoPlan};

#[test]
fn qualified_ref_maps_supported_kinds() {
    assert_eq!(
        qualified_ref("branch", "main").as_deref(),
        Some("refs/heads/main:refs/heads/main")
    );
    assert_eq!(
        qualified_ref("tag", "v1.0.0").as_deref(),
        Some("refs/tags/v1.0.0:refs/tags/v1.0.0")
    );
}

#[test]
fn qualified_ref_accepts_permitted_punctuation_and_non_ascii_whitespace() {
    assert_eq!(
        qualified_ref("branch", "feature/topic").as_deref(),
        Some("refs/heads/feature/topic:refs/heads/feature/topic")
    );
    assert_eq!(
        qualified_ref("tag", "release\u{2003}candidate").as_deref(),
        Some("refs/tags/release\u{2003}candidate:refs/tags/release\u{2003}candidate")
    );
    assert_eq!(
        qualified_ref("branch", "left\u{000b}right").as_deref(),
        Some("refs/heads/left\u{000b}right:refs/heads/left\u{000b}right")
    );
}

#[test]
fn qualified_ref_rejects_unknown_kinds_and_malformed_names() {
    assert_eq!(qualified_ref("", "main"), None);
    assert_eq!(qualified_ref("heads", "main"), None);
    assert_eq!(qualified_ref("Branch", "main"), None);
    assert_eq!(qualified_ref("branch", ""), None);
    assert_eq!(qualified_ref("branch", "/main"), None);
    assert_eq!(qualified_ref("branch", "release:v1"), None);

    for whitespace in [' ', '\t', '\n', '\r', '\u{000c}'] {
        let name = format!("left{whitespace}right");
        assert_eq!(
            qualified_ref("branch", &name),
            None,
            "accepted ASCII whitespace U+{:04X}",
            whitespace as u32
        );
    }
}

#[test]
fn qualified_ref_does_not_mutate_the_name() {
    let name = String::from("feature/nested");
    let before = name.clone();
    let result = qualified_ref("branch", &name);

    assert_eq!(name, before);
    assert_eq!(
        result.as_deref(),
        Some("refs/heads/feature/nested:refs/heads/feature/nested")
    );
}

#[test]
fn project_slug_handles_common_remote_forms() {
    assert_eq!(project_slug("https://host/org/repo.git").as_deref(), Some("repo"));
    assert_eq!(project_slug("git@host:org/repo.git").as_deref(), Some("repo"));
    assert_eq!(project_slug("org:repo").as_deref(), Some("repo"));
    assert_eq!(project_slug("repo").as_deref(), Some("repo"));
    assert_eq!(project_slug("repo////").as_deref(), Some("repo"));
}

#[test]
fn project_slug_trims_only_surrounding_ascii_whitespace() {
    assert_eq!(
        project_slug(" \t\n\u{000c}https://host/org/repo.git///\r\n\u{000c}").as_deref(),
        Some("repo")
    );
    assert_eq!(project_slug("\u{2003}repo.git").as_deref(), Some("\u{2003}repo"));
    assert_eq!(project_slug("repo.git\u{2003}").as_deref(), Some("repo.git\u{2003}"));
    assert_eq!(
        project_slug("host/\u{2003}repo.git\u{2003}///").as_deref(),
        Some("\u{2003}repo.git\u{2003}")
    );
}

#[test]
fn project_slug_removes_exactly_one_git_suffix() {
    assert_eq!(project_slug("repo.git").as_deref(), Some("repo"));
    assert_eq!(project_slug("repo.git.git").as_deref(), Some("repo.git"));
    assert_eq!(project_slug("repo.GIT").as_deref(), Some("repo.GIT"));
}

#[test]
fn project_slug_rejects_empty_or_empty_final_components() {
    for remote in [
        "",
        " ",
        "\t\r\n\u{000c}",
        "/",
        "////",
        ":",
        "host:",
        "host/path:",
        ".git",
        "host/.git",
        "host/.git///",
    ] {
        assert_eq!(project_slug(remote), None, "unexpected slug for {remote:?}");
    }
}

#[test]
fn project_slug_applies_operations_in_the_specified_order() {
    assert_eq!(project_slug("host/ \t/").as_deref(), Some(" \t"));
    assert_eq!(project_slug("host/repo.git///   ").as_deref(), Some("repo"));
    assert_eq!(project_slug("host/path:leaf.git").as_deref(), Some("leaf"));
}

#[test]
fn project_slug_does_not_mutate_the_remote() {
    let remote = String::from("  git@host:org/repo.git///  ");
    let before = remote.clone();
    let result = project_slug(&remote);

    assert_eq!(remote, before);
    assert_eq!(result.as_deref(), Some("repo"));
}

#[test]
fn tracked_refs_preserves_category_and_insertion_order() {
    let plan = RepoPlan {
        primary: "main".to_string(),
        supporting: vec!["beta".to_string(), "alpha".to_string(), "release".to_string()],
        tags: vec!["v2".to_string(), "v1".to_string()],
    };

    assert_eq!(
        plan.tracked_refs(),
        vec![
            "refs/heads/main:refs/heads/main",
            "refs/heads/beta:refs/heads/beta",
            "refs/heads/alpha:refs/heads/alpha",
            "refs/heads/release:refs/heads/release",
            "refs/tags/v2:refs/tags/v2",
            "refs/tags/v1:refs/tags/v1",
        ]
    );
}

#[test]
fn tracked_refs_skips_invalid_entries_and_keeps_first_duplicate() {
    let plan = RepoPlan {
        primary: "/invalid".to_string(),
        supporting: vec![
            "dev".to_string(),
            "bad name".to_string(),
            "dev".to_string(),
            "next".to_string(),
            "bad:name".to_string(),
            "next".to_string(),
        ],
        tags: vec![
            "v1".to_string(),
            "".to_string(),
            "v1".to_string(),
            "/v2".to_string(),
            "v3".to_string(),
        ],
    };

    assert_eq!(
        plan.tracked_refs(),
        vec![
            "refs/heads/dev:refs/heads/dev",
            "refs/heads/next:refs/heads/next",
            "refs/tags/v1:refs/tags/v1",
            "refs/tags/v3:refs/tags/v3",
        ]
    );
}

#[test]
fn tracked_refs_keeps_identical_branch_and_tag_names_distinct() {
    let plan = RepoPlan {
        primary: "same".to_string(),
        supporting: vec!["same".to_string()],
        tags: vec!["same".to_string(), "same".to_string()],
    };

    assert_eq!(
        plan.tracked_refs(),
        vec![
            "refs/heads/same:refs/heads/same",
            "refs/tags/same:refs/tags/same",
        ]
    );
}

#[test]
fn tracked_refs_is_stable_and_does_not_mutate_the_plan() {
    let plan = RepoPlan {
        primary: "main".to_string(),
        supporting: vec!["dev".to_string(), "dev".to_string(), "bad name".to_string()],
        tags: vec!["main".to_string(), "v1".to_string()],
    };
    let before = plan.clone();

    let first = plan.tracked_refs();
    let second = plan.tracked_refs();

    assert_eq!(first, second);
    assert_eq!(plan, before);
}

#[test]
fn tracked_refs_handles_empty_collections_and_invalid_primary() {
    let valid = RepoPlan {
        primary: "main".to_string(),
        supporting: Vec::new(),
        tags: Vec::new(),
    };
    assert_eq!(
        valid.tracked_refs(),
        vec!["refs/heads/main:refs/heads/main"]
    );

    let empty = RepoPlan {
        primary: String::new(),
        supporting: Vec::new(),
        tags: Vec::new(),
    };
    assert!(empty.tracked_refs().is_empty());
}

