import unittest
from collections import UserDict
from collections.abc import Mapping
from types import MappingProxyType

from solution import WorkMessage


class SimpleMapping(Mapping):
    def __init__(self, data):
        self._data = data

    def __getitem__(self, key):
        return self._data[key]

    def __iter__(self):
        return iter(self._data)

    def __len__(self):
        return len(self._data)


class WorkMessageTests(unittest.TestCase):
    def test_valid_job_and_boundaries(self):
        for priority in (0, 9):
            message = WorkMessage(
                "job", {"id": "job-1", "priority": priority, "tags": []}
            )
            self.assertEqual(message.kind, "job")
            self.assertEqual(
                message.fields,
                {"id": "job-1", "priority": priority, "tags": []},
            )
            self.assertTrue(message.is_consistent())

    def test_valid_job_tags_and_whitespace_are_not_treated_as_empty(self):
        fields = {"id": " ", "priority": 5, "tags": [" ", "x", "X"]}
        message = WorkMessage("job", fields)
        self.assertEqual(message.fields, fields)
        self.assertTrue(message.is_consistent())

    def test_valid_replies(self):
        for accepted in (False, True):
            message = WorkMessage("reply", {"id": "reply-1", "accepted": accepted})
            self.assertEqual(message.kind, "reply")
            self.assertEqual(
                message.fields, {"id": "reply-1", "accepted": accepted}
            )
            self.assertTrue(message.is_consistent())

    def test_non_mapping_fields_raise_type_error(self):
        for fields in (None, [], (), "id", 3):
            with self.subTest(fields=fields):
                with self.assertRaises(TypeError):
                    WorkMessage("job", fields)

    def test_general_mapping_implementations_are_accepted(self):
        user_fields = UserDict({"id": "u", "priority": 3, "tags": ["a"]})
        simple_fields = SimpleMapping({"id": "s", "accepted": True})
        backing = {"id": "p", "priority": 4, "tags": ["b"]}
        proxy_fields = MappingProxyType(backing)

        self.assertEqual(
            WorkMessage("job", user_fields).fields,
            {"id": "u", "priority": 3, "tags": ["a"]},
        )
        self.assertEqual(
            WorkMessage("reply", simple_fields).fields,
            {"id": "s", "accepted": True},
        )
        self.assertEqual(
            WorkMessage("job", proxy_fields).fields,
            {"id": "p", "priority": 4, "tags": ["b"]},
        )

    def test_invalid_kinds_raise_value_error(self):
        valid_fields = {"id": "x", "accepted": True}
        for kind in ("", "Job", "response", None, 1, True, [], {}):
            with self.subTest(kind=kind):
                with self.assertRaises(ValueError):
                    WorkMessage(kind, valid_fields)

    def test_missing_extra_and_wrong_keys_raise_value_error(self):
        invalid_jobs = (
            {},
            {"id": "x", "priority": 1},
            {"id": "x", "priority": 1, "tags": [], "extra": 2},
            {"id": "x", "priority": 1, "tag": []},
            {"id": "x", "priority": 1, "tags": [], 0: "extra"},
        )
        for fields in invalid_jobs:
            with self.subTest(fields=fields):
                with self.assertRaises(ValueError):
                    WorkMessage("job", fields)

        invalid_replies = (
            {},
            {"id": "x"},
            {"accepted": False},
            {"id": "x", "accepted": False, "extra": 0},
            {"id": "x", "accept": False},
        )
        for fields in invalid_replies:
            with self.subTest(fields=fields):
                with self.assertRaises(ValueError):
                    WorkMessage("reply", fields)

    def test_id_type_and_value_validation(self):
        for kind, remainder in (
            ("job", {"priority": 1, "tags": []}),
            ("reply", {"accepted": True}),
        ):
            with self.subTest(kind=kind, case="empty"):
                with self.assertRaises(ValueError):
                    WorkMessage(kind, {"id": "", **remainder})

            for bad_id in (None, 0, False, [], b"x"):
                with self.subTest(kind=kind, bad_id=bad_id):
                    with self.assertRaises(TypeError):
                        WorkMessage(kind, {"id": bad_id, **remainder})

    def test_priority_type_validation_rejects_booleans(self):
        for priority in (True, False, None, 1.0, "1", b"1"):
            with self.subTest(priority=priority):
                with self.assertRaises(TypeError):
                    WorkMessage(
                        "job", {"id": "x", "priority": priority, "tags": []}
                    )

    def test_priority_value_validation(self):
        for priority in (-1, 10, -(10**100), 10**100):
            with self.subTest(priority=priority):
                with self.assertRaises(ValueError):
                    WorkMessage(
                        "job", {"id": "x", "priority": priority, "tags": []}
                    )

    def test_tags_must_be_a_list(self):
        for tags in (None, (), set(), "tag", {"tag": True}):
            with self.subTest(tags=tags):
                with self.assertRaises(TypeError):
                    WorkMessage(
                        "job", {"id": "x", "priority": 1, "tags": tags}
                    )

    def test_tag_element_types_and_values(self):
        for tags in ([1], [None], [False], [b"x"], ["ok", 2]):
            with self.subTest(tags=tags):
                with self.assertRaises(TypeError):
                    WorkMessage(
                        "job", {"id": "x", "priority": 1, "tags": tags}
                    )

        for tags in ([""], ["ok", ""]):
            with self.subTest(tags=tags):
                with self.assertRaises(ValueError):
                    WorkMessage(
                        "job", {"id": "x", "priority": 1, "tags": tags}
                    )

    def test_duplicate_tags_raise_value_error(self):
        for tags in (["dup", "dup"], ["a", "b", "a"]):
            with self.subTest(tags=tags):
                with self.assertRaises(ValueError):
                    WorkMessage(
                        "job", {"id": "x", "priority": 1, "tags": tags}
                    )

    def test_accepted_must_be_exactly_boolean(self):
        for accepted in (0, 1, None, "true", [], 1.0):
            with self.subTest(accepted=accepted):
                with self.assertRaises(TypeError):
                    WorkMessage("reply", {"id": "x", "accepted": accepted})

    def test_constructor_isolates_job_from_mapping_and_nested_list(self):
        tags = ["initial"]
        supplied = {"id": "job", "priority": 2, "tags": tags}
        message = WorkMessage("job", supplied)

        tags.append("through-list")
        supplied["id"] = "changed"
        supplied["priority"] = 9
        supplied["tags"].append("through-mapping")
        supplied["extra"] = "new"

        self.assertEqual(
            message.fields,
            {"id": "job", "priority": 2, "tags": ["initial"]},
        )
        self.assertTrue(message.is_consistent())

    def test_constructor_isolates_from_mapping_proxy_backing_data(self):
        tags = ["a"]
        backing = {"id": "proxy", "priority": 6, "tags": tags}
        message = WorkMessage("job", MappingProxyType(backing))

        tags.append("b")
        backing["id"] = "changed"

        self.assertEqual(
            message.fields,
            {"id": "proxy", "priority": 6, "tags": ["a"]},
        )
        self.assertTrue(message.is_consistent())

    def test_mapping_proxy_reply_is_valid_and_isolated(self):
        backing = {"id": "proxy-reply", "accepted": False}
        message = WorkMessage("reply", MappingProxyType(backing))

        self.assertEqual(message.kind, "reply")
        self.assertEqual(
            message.fields, {"id": "proxy-reply", "accepted": False}
        )
        self.assertTrue(message.is_consistent())

        backing["id"] = "changed"
        backing["accepted"] = True
        backing["extra"] = "new"
        returned = message.fields
        returned["id"] = "returned-change"
        returned["accepted"] = True

        self.assertEqual(message.kind, "reply")
        self.assertEqual(
            message.fields, {"id": "proxy-reply", "accepted": False}
        )
        self.assertTrue(message.is_consistent())

    def test_each_fields_access_is_a_fresh_deep_copy(self):
        message = WorkMessage(
            "job", {"id": "job", "priority": 7, "tags": ["a", "b"]}
        )
        first = message.fields
        second = message.fields

        self.assertIsNot(first, second)
        self.assertIsNot(first["tags"], second["tags"])

        first["id"] = "mutated"
        first["priority"] = 0
        first["tags"].append("mutated")
        first["extra"] = True
        second["tags"].clear()

        self.assertEqual(
            message.fields,
            {"id": "job", "priority": 7, "tags": ["a", "b"]},
        )
        self.assertTrue(message.is_consistent())

    def test_reply_fields_access_is_isolated(self):
        supplied = {"id": "reply", "accepted": False}
        message = WorkMessage("reply", supplied)
        supplied["accepted"] = True

        returned = message.fields
        returned["id"] = "changed"
        returned["accepted"] = True

        self.assertEqual(message.fields, {"id": "reply", "accepted": False})
        self.assertTrue(message.is_consistent())

    def test_kind_and_fields_properties_are_read_only(self):
        message = WorkMessage("reply", {"id": "x", "accepted": True})
        with self.assertRaises(AttributeError):
            message.kind = "job"
        with self.assertRaises(AttributeError):
            message.fields = {"id": "y", "accepted": False}

        self.assertEqual(message.kind, "reply")
        self.assertEqual(message.fields, {"id": "x", "accepted": True})
        self.assertTrue(message.is_consistent())


